/// \file
/// This file declares the targeting of the RegisterBankInfo class
//  for AIE2ps.
/// \todo This should be generated by TableGen.
//===----------------------------------------------------------------------===//

#ifndef LLVM_LIB_TARGET_AIE2PS_AIE2PSREGISTERBANKINFO_H
#define LLVM_LIB_TARGET_AIE2PS_AIE2PSREGISTERBANKINFO_H

#include "AIEBaseRegisterBankInfo.h"

#define GET_REGBANK_DECLARATIONS
#include "AIE2PSGenRegisterBank.inc"

namespace llvm {

class TargetRegisterInfo;

class AIE2PSGenRegisterBankInfo : public AIEBaseRegisterBankInfo {
protected:
  static RegisterBankInfo::PartialMapping PartMappings[];
  static RegisterBankInfo::ValueMapping ValMappings[];
  // Update these values if you modify AIE2PSGenRegisterBankInfo::ValMappings[]
  // to ensure consistency with the register bank mappings.
  enum ValueMappingIdx {
    InvalidIdx = 0,
    First3OpsIdx = 1,
    FirstVecOpsIdx = 16,
    FirstAccOpsIdx = 26,
    LastOpsIdx = 31,
    DistanceBetweenRegBanks = 3,
    DistanceBetweenAccRegBanks = 1,
    DistanceBetweenFifoRegBanks = 1,
    S128_Idx = 28,
    FirstFifoOpsIdx = 30
  };

  /// Get the pointer to the ValueMapping representing the RegisterBank
  /// at \p RBIdx with a size of \p Size.
  ///
  /// The returned mapping works for instructions with the same kind of
  /// operands for up to 3 operands.
  ///
  /// \pre \p RBIdx != PartialMappingIdx::None
  const RegisterBankInfo::ValueMapping *
  getValueMapping(PartialMappingIdx RBIdx, unsigned Size) const override;

  PartialMappingIdx getPartialMappingIdx(const LLT &Ty) const override;
  PartialMappingIdx getAccPartialMappingIdx(const LLT &Ty) const override;
  PartialMappingIdx getFifoPartialMappingIdx(const LLT &Ty) const;
  PartialMappingIdx getPartialMappingIdxFromBankAndType(
      std::optional<const RegisterBank *> RegBank, const LLT &Ty) const;

#define GET_TARGET_REGBANK_CLASS
#include "AIE2PSGenRegisterBank.inc"
};

/// This class provides the information for the target register banks.
class AIE2PSRegisterBankInfo final : public AIE2PSGenRegisterBankInfo {
  void setAIEGenericInstrMapping(
      const MachineInstr &MI, SmallVector<unsigned, 4> &OpSize,
      SmallVector<PartialMappingIdx, 4> &OpRegBankIdx) const override;

public:
  AIE2PSRegisterBankInfo(const TargetRegisterInfo &TRI);
  InstructionMappings
  getInstrAlternativeMappings(const MachineInstr &MI) const override;
  const InstructionMapping &
  getInstrMapping(const MachineInstr &MI) const override;
  const RegisterBank &getRegBankFromRegClass(const TargetRegisterClass &RC,
                                             LLT) const override;
  std::optional<const RegisterBank *>
  getPreferredRegBankForVectorTy(const MachineRegisterInfo &MRI,
                                 const TargetRegisterInfo &TRI,
                                 Register Reg) const;
  std::optional<const RegisterBank *>
  getRegBankForVectorTy(const MachineRegisterInfo &MRI,
                        const TargetRegisterInfo &TRI, const MachineInstr &MI,
                        Register Reg) const;
  void applyMappingImpl(MachineIRBuilder &Builder,
                        const OperandsMapper &OpdMapper) const override;
};
} // end namespace llvm
#endif
